mkdir -p artifacts && node -e '
const fs=require("fs");
const input=JSON.parse(fs.readFileSync("input.json","utf8"));
const orders=input.orders.slice().sort((a,b)=>{
  if(a.priority!==b.priority) return a.priority-b.priority;
  return a.id<b.id?-1:(a.id>b.id?1:0);
});
const remaining={};
for(const sku of Object.keys(input.stock)) remaining[sku]=input.stock[sku];
const out=[];
for(const o of orders){
  const q=Number(o.quantity);
  if(remaining[o.sku]>=q){
    remaining[o.sku]-=q;
    out.push({id:String(o.id),allocated:q});
  }else{
    out.push({id:String(o.id),allocated:0});
  }
}
fs.writeFileSync("artifacts/result.json",JSON.stringify({orders:out,remaining}));
'

node -e '
const fs=require("fs");
const input=JSON.parse(fs.readFileSync("input.json","utf8"));
const res=JSON.parse(fs.readFileSync("artifacts/result.json","utf8"));
const expected=input.orders.slice().sort((a,b)=>a.priority!==b.priority?a.priority-b.priority:(a.id<b.id?-1:(a.id>b.id?1:0)));
const rem={...input.stock};
const expOut=[];
for(const o of expected){
  if(rem[o.sku]>=o.quantity){rem[o.sku]-=o.quantity;expOut.push({id:String(o.id),allocated:o.quantity});}
  else expOut.push({id:String(o.id),allocated:0});
}
if(JSON.stringify(res.orders)!==JSON.stringify(expOut)) throw new Error("orders mismatch: "+JSON.stringify(res.orders));
if(JSON.stringify(res.remaining)!==JSON.stringify(rem)) throw new Error("remaining mismatch: "+JSON.stringify(res.remaining));
const keys=Object.keys(res.remaining).sort();
const inKeys=Object.keys(input.stock).sort();
if(JSON.stringify(keys)!==JSON.stringify(inKeys)) throw new Error("sku set mismatch");
if(Object.keys(res).sort().join()!=="orders,remaining") throw new Error("extra/missing top-level fields");
for(const o of res.orders){
  if(Object.keys(o).sort().join()!=="allocated,id") throw new Error("extra fields in order");
  if(typeof o.allocated!=="number"||!Number.isInteger(o.allocated)) throw new Error("non-integer allocated");
}
console.log("OK");
'
